(async () => {
const out = {};
const t = (name, f) => { try { out[name] = f(); } catch (e) { out[name] = 'throws ' + e.name + ': ' + e.message; } };
t('ct NaN', () => { v.currentTime = NaN; return v.currentTime; });
t('ct Inf', () => { v.currentTime = Infinity; return v.currentTime; });
t('ct -5', () => { v.currentTime = -5; return v.currentTime; });
t('ct 7', () => { v.currentTime = 7; return v.currentTime; });
t('vol -1', () => { v.volume = -1; return v.volume; });
t('vol NaN', () => { v.volume = NaN; return v.volume; });
t('vol 1.5', () => { v.volume = 1.5; return v.volume; });
t('vol 0.3', () => { v.volume = 0.3; return v.volume; });
t('vol str', () => { v.volume = '0.7'; return v.volume; });
t('vol 1e-7', () => { v.volume = 1e-7; return v.volume; });
for (const r of [0, 0.0625, 0.06, 0.0624, 0.5, 2, 4, 15.9, 16, 16.1, -1, 100, 1e-9, 1e9, 0.07]) t('rate ' + r, () => { v.playbackRate = r; return v.playbackRate; });
for (const r of [0, 0.0625, 0.06, 0.0624, 0.5, 2, 4, 15.9, 16, 16.1, -1, 100, 1e-9, 1e9, 0.07]) t('drate ' + r, () => { const x = document.createElement('video'); x.defaultPlaybackRate = r; return [x.defaultPlaybackRate, x.playbackRate]; });
t('rate then drate', () => { const x = document.createElement('video'); x.playbackRate = 2; x.defaultPlaybackRate = 3; return [x.defaultPlaybackRate, x.playbackRate]; });
t('rate str', () => { v.playbackRate = '1.5'; return v.playbackRate; });
t('rate NaN', () => { v.playbackRate = NaN; return v.playbackRate; });
t('rate Inf', () => { v.playbackRate = Infinity; return v.playbackRate; });
for (const r of [123456789, 1234567, 100000, 12345.678, 0.00012345, 0.000012345, 1.5e-7, 2.5e300, 17.123456789, 999999.5, 0.99999949, -0.5, -1e-9, -1e9]) t('rate message ' + r, () => { v.playbackRate = r; return v.playbackRate; });
const seq = [];
const y = document.createElement('video');
y.addEventListener('ratechange', () => seq.push('ratechange ' + y.defaultPlaybackRate + '/' + y.playbackRate));
for (const [k, val] of [['p', 2], ['p', 100], ['p', 2], ['d', 3], ['d', 100], ['d', 3], ['d', 0.5], ['p', 0], ['d', 0], ['p', 0.0625]]) {
  try { if (k === 'p') y.playbackRate = val; else y.defaultPlaybackRate = val; seq.push(k + val + ' ok'); } catch (e) { seq.push(k + val + ' ' + e.name); }
  await new Promise(r => setTimeout(r, 20));
}
out['rate events'] = seq;
t('muted', () => { v.muted = true; return [v.muted, v.defaultMuted, v.hasAttribute('muted')]; });
t('defaultMuted', () => { v.defaultMuted = true; v.muted = false; return [v.muted, v.defaultMuted, v.hasAttribute('muted')]; });
t('played empty', () => [v.played.length, v.ended, v.paused, v.seeking, v.readyState, v.networkState]);
t('Audio()', () => { const x = new Audio(); return [x.preload, x.getAttribute('preload'), x.src, x.networkState, x.paused, x.readyState, x.muted, x.volume, x.constructor.name, x.isConnected, x.parentNode]; });
t('Audio(src)', () => { const x = new Audio('b.mp3'); return [x.preload, x.getAttribute('src'), x.src.slice(-5), x.networkState]; });
t('Audio called', () => Audio());
t('Audio.length', () => [Audio.length, Audio.name, typeof Audio, Object.getOwnPropertyDescriptor(Audio.prototype === undefined ? {} : Audio, 'prototype') && Audio.prototype === HTMLAudioElement.prototype]);
t('Audio(undefined)', () => new Audio(undefined).hasAttribute('src'));
t('Audio(null)', () => new Audio(null).getAttribute('src'));
t('pause returns', () => String(v.pause()));
const p = v.play();
t('play no src', () => [v.paused, v.networkState]);
let st = 'pending';
p.then(() => st = 'resolved', e => st = e.name + ': ' + e.message);
await new Promise(r => setTimeout(r, 300));
out['promise after 300'] = st;
v.pause();
await new Promise(r => setTimeout(r, 10));
out['promise after pause'] = st;
out['paused after'] = v.paused;
const evs = [];
['play','pause','timeupdate','waiting','ratechange','volumechange','emptied','loadstart','abort','error','seeking'].forEach(n => a.addEventListener(n, () => evs.push(n)));
a.play().catch(e => evs.push('rej ' + e.name));
a.volume = 0.5; a.muted = true; a.muted = true; a.playbackRate = 1; a.playbackRate = 1.5; a.defaultPlaybackRate = 1.5; a.defaultPlaybackRate = 1.5;
a.pause(); a.pause();
a.currentTime = 3;
await new Promise(r => setTimeout(r, 300));
out['events'] = evs;
out['a state'] = [a.currentTime, a.paused, a.networkState, a.readyState, a.error, a.played.length];
t('load()', () => { a.load(); return [a.networkState, a.playbackRate, a.volume, a.muted, a.currentTime]; });
t('played toString', () => Object.prototype.toString.call(v.played));
t('ended loop', () => { v.loop = true; return v.ended; });
return out;
})()
